insert into public.iskra_shared_kb (topic, topic_norm, body, tags) values
  ('Какое давление считается высоким', public.iskra_kb_norm('Какое давление считается высоким'), 'Для взрослого высокое давление — от 140/90 мм рт. ст. и выше, если измерено в спокойном состоянии дважды с перерывом. Цифры 130–139/85–89 называют повышенным. Норма — примерно 120/80. Измеряй сидя, рука на столе, после 5 минут покоя, манжетой на плече. Однократное высокое число — не диагноз, а повод мерить неделю и идти к врачу.', 'здоровье, давление, гипертония'),
  ('Простуда и антибиотики', public.iskra_kb_norm('Простуда и антибиотики'), 'Большинство простуд — вирусы, на них антибиотики не действуют. ОРВИ обычно проходит за 7–10 дней: покой, питьё, при необходимости жаропонижающее. Антибиотики нужны при бактериальной инфекции, и назначает их врач. Если температура выше 38,5 держится больше 3 дней, появилась одышка, сильная боль в груди или не спадает после улучшения — иди к врачу.', 'здоровье, орви, простуда, антибиотики'),
  ('Какую температуру сбивать', public.iskra_kb_norm('Какую температуру сбивать'), 'Норма у взрослого — от 36,0 до 37,2. Жар до 38,5 обычно не сбивают: он помогает организму. Жаропонижающее — при плохом самочувствии, а не по одной цифре. Пей больше, чем хочется: при жаре теряется жидкость. Срочно к врачу: температура выше 39–40, судороги, спутанность, сыпь, невозможность пить. У детей порог ниже — смотри состояние, а не градусник.', 'здоровье, температура, жар'),
  ('Сколько нужно спать', public.iskra_kb_norm('Сколько нужно спать'), 'Взрослому нужно 7–9 часов, подростку 8–10. Недосып накапливается: две ночи по 5 часов не компенсируются одной ночью по 10. За час до сна убери яркий экран, ложись в одно время, кофеин — не позже 6 часов до сна. Если спишь по 8 часов и всё равно разбит месяц — это повод к врачу, а не к кофе.', 'здоровье, сон, режим'),
  ('Помощь при порезе и ожоге', public.iskra_kb_norm('Помощь при порезе и ожоге'), 'Порез: промой водой, останови кровь давлением чистой салфеткой 5–10 минут, обработай края, закрой пластырем. Не лей перекись в глубину раны. Ожог: охлаждай прохладной водой 15–20 минут, не мажь маслом и не прокалывай пузыри. К врачу: глубокая рана, ожог больше ладони, лицо, кисти, суставы, а также если рана загрязнена (нужна прививка от столбняка).', 'здоровье, первая помощь, порез, ожог'),
  ('Витамин D: когда пить', public.iskra_kb_norm('Витамин D: когда пить'), 'Витамин D нужен для костей и мышц; он же вырабатывается под солнцем. Летом на улице его обычно хватает, зимой у многих он низкий. Пить «для профилактики» без анализа — так себе идея: доза зависит от исходного уровня. Лучше сдать анализ 25(OH)D и обсудить дозу с врачом. Передозировка возможна, витамин D накапливается.', 'здоровье, витамин d, дефицит'),
  ('Содержимое домашней аптечки', public.iskra_kb_norm('Содержимое домашней аптечки'), 'Базовый набор: жаропонижающее и обезболивающее, антигистаминное, средство от диареи и от запоров, регидратационные пакеты, антисептик, пластыри, бинт, ножницы, термометр, тонометр. Проверяй сроки годности раз в полгода. Храни в сухом месте, не в ванной. Лекарства, которые принимаешь постоянно, держи с запасом на неделю отдельно.', 'здоровье, аптечка, лекарства'),
  ('Как не заразиться от больного дома', public.iskra_kb_norm('Как не заразиться от больного дома'), 'Проветривай комнату каждые 1–2 часа по 10 минут: в воздухе вируса меньше, чем в затхлой комнате. Больному — отдельная посуда и полотенце, чаще мой руки с мылом по 20 секунд. Маска нужна прежде всего на больном. Влажная уборка и увлажнитель снижают пыль, которую вдыхает больной. Витамины и чеснок как защита не доказаны.', 'здоровье, профилактика, вирус'),
  ('Бюджет по правилу 50/30/20', public.iskra_kb_norm('Бюджет по правилу 50/30/20'), 'Простое деление дохода: 50% на обязательное (жильё, еда, транспорт, связь), 30% на желаемое (кафе, покупки, поездки), 20% на будущее (накопления, долги, инвестиции). Это не догма, а точка отсчёта. Веди траты две недели, чтобы понять реальные цифры: обычно расходы выше, чем кажется.', 'финансы, бюджет, зарплата'),
  ('Подушка безопасности', public.iskra_kb_norm('Подушка безопасности'), 'Запас на 3–6 месяцев обычных расходов (при нестабильном доходе — до 12). Лежит там, где можно забрать за день: накопительный счёт или вклад. Живёт отдельно от повседневной карты, иначе тратится. Считай по месячным обязательным расходам, а не по доходу. Собрав подушку, переходи к долгосрочным целям.', 'финансы, накопления, резерв'),
  ('Сложный процент', public.iskra_kb_norm('Сложный процент'), 'Процент, начисленный на процент: 100 000 под 10% годовых с капитализацией дают за год 110 000, за 10 лет около 259 000, если вкладывать проценты обратно. Считать просто: сумма × (1 + ставка)^годы. Поэтому время важнее суммы: старт на 10 лет раньше почти всегда даёт больше, чем удвоенный взнос.', 'финансы, вклад, проценты'),
  ('Кредит и рассрочка: отличия', public.iskra_kb_norm('Кредит и рассрочка: отличия'), 'Кредит — это деньги под процент, банк платит за тебя продавцу и ждёт с процентом. Рассрочка от магазина обычно без процентов, но цена заложена в товар или есть плата за обслуживание. Настоящая «переплата 0%» бывает не всегда: читай график платежей и полную стоимость кредита. Просрочка портит кредитную историю в обоих случаях.', 'финансы, кредит, рассрочка'),
  ('Что такое инфляция простыми словами', public.iskra_kb_norm('Что такое инфляция простыми словами'), 'Инфляция — обесценивание денег: товары дорожают, на ту же сумму покупаешь меньше. Если цены растут на 8% в год, деньги на карте без процентов за год теряют 8% покупательной способности. Поэтому резерв кладут на счёт с процентом, а длинные цели — в инструменты, которые обгоняют инфляцию. Считается по изменению цен на корзину товаров.', 'финансы, инфляция, деньги'),
  ('Мошенники по телефону и карте', public.iskra_kb_norm('Мошенники по телефону и карте'), 'Настоящий банк никогда не спрашивает CVV, пароль из СМС и код отмены перевода. Любой звонок «из банка», «из полиции», «служба безопасности» — сбросить и перезвонить по номеру с обратной стороны карты. Не переводи «на безопасный счёт» — такого счёта не существует. Если деньги уже ушли — звони в банк и в полицию сразу, первые часы важны.', 'финансы, мошенники, безопасность, карта'),
  ('Зачем нужна страховка', public.iskra_kb_norm('Зачем нужна страховка'), 'Страховка перекладывает редкий крупный риск на компанию: платишь немного всегда, чтобы не платить много однажды. Обязательная в России — ОСАГО для автомобиля. Медицинская, квартирная и страховая жизнь — добровольные. Бери те риски, удар по которым ты не переживёшь сам, а мелочь вроде телефона дешевле копить.', 'финансы, страховка, осаго'),
  ('Возврат товара в магазин', public.iskra_kb_norm('Возврат товара в магазин'), 'Товар надлежащего качества можно вернуть в течение 14 дней, не считая дня покупки: он не был в употреблении, сохранены ярлыки и упаковка, есть чек (или другой документ подтверждения). Товар из перечня невозвратных (лекарства, бельё, ювелирка, животные, книги) вернуть нельзя, если он качественный. Если товар бракованный — срок 2 года и другие правила.', 'право, возврат, магазин, покупка'),
  ('Гарантия: что делать с браком', public.iskra_kb_norm('Гарантия: что делать с браком'), 'По закону о защите прав потребителей при обнаружении брака ты выбираешь сам: возврат денег, замена, ремонт или скидка. Гарантийный срок — от 14 дней до 5 лет, зависит от товара. Магазин обязан принять претензию письменно: два экземпляра, отметка о получении. Проверка качества обычно до 10 дней, ремонт до 45 дней. Срок гарантии продлевается на время ремонта.', 'право, гарантия, брак, ремонт'),
  ('Отпуск по Трудовому кодексу', public.iskra_kb_norm('Отпуск по Трудовому кодексу'), 'Каждый год — не менее 28 календарных дней оплачиваемого отпуска (у ряда профессий больше). Отпускные платят не позднее чем за 3 календарных дня до начала. Право на первый отпуск — через 6 месяцев работы. Отпуск делят так, чтобы одна часть была не меньше 14 дней. Отзыв — только с согласия работника, а некоторым категориям отказ разрешён.', 'право, работа, отпуск'),
  ('Испытательный срок при приёме', public.iskra_kb_norm('Испытательный срок при приёме'), 'Обычно до 3 месяцев, для руководителей и отдельных категорий до 6, для срочных договоров на 2–6 месяцев — до 2 недель. Испытание устанавливается только в трудовом договоре: если условия там нет, испытания нет. Больничный в этот период оплачивается. Уволить на испытании можно, предупредив за 3 дня, и с письменной причиной.', 'право, работа, договор'),
  ('Что должно быть в трудовом договоре', public.iskra_kb_norm('Что должно быть в трудовом договоре'), 'Обязательно: место работы, трудовая функция (должность), дата начала, срок договора, условия оплаты, режим работы и отдыха, условия труда, гарантии и компенсации. Договор — в двух экземплярах, один твой; забери с подписью и печатью. Приём оформляют приказом, а сведения идут в трудовую книжку или электронно. Никогда не подписывай пустой бланк.', 'право, работа, договор'),
  ('Переменная часть зарплаты', public.iskra_kb_norm('Переменная часть зарплаты'), 'Оклад — гарантированная часть, её размер обязателен в договоре. Премия может быть правом, а не обязанностью работодателя, если в локальном акте не сказано иное. Зарплата выплачивается не реже двух раз в месяц, с расчётным листком. Задерживают больше 15 дней — можно письменно приостановить работу, но сначала уточни условия в договоре.', 'право, работа, зарплата, премия'),
  ('Резюме, на которое отвечают', public.iskra_kb_norm('Резюме, на которое отвечают'), 'Одна страница на первые годы, две — с опытом. Сверху — кто ты и что ищешь одной строкой. Опыт — результатами: «сократил обработку заказов с 3 дней до 3 часов», а не «занимался заказами». Навыки — конкретные инструменты. Убери фото в пиджаке и «стрессоустойчивость». Проверь, что контакты верные, и подгоняй ключевые слова под вакансию.', 'работа, резюме, поиск работы'),
  ('Собеседование: как готовиться', public.iskra_kb_norm('Собеседование: как готовиться'), 'Изучи компанию и вакансию, подготовь три истории в формате «ситуация — что сделал — результат». Заранее ответь себе: почему сюда, почему ты, о чём хочешь знать. На вопрос о слабом месте — реальная слабость и что с ней делаешь. Вопросы работодателю задавай про задачи, команду, как измеряют успех. Отправь короткое письмо-спасибо в тот же день.', 'работа, собеседование'),
  ('Метод помидора', public.iskra_kb_norm('Метод помидора'), '25 минут работы, 5 минут перерыва, после четырёх циклов — длинный перерыв 15–30 минут. Правило простое: в эти 25 минут — одна задача и никаких чатов. Если отвлёкся — не начинай заново, просто вернись. Работает потому, что убирает развилку «делать или не делать» и не даёт устать.', 'работа, учеба, время, прокрастинация'),
  ('Как учиться по интервалам', public.iskra_kb_norm('Как учиться по интервалам'), 'Забывание идёт быстро в первые сутки. Повторяй материал через 1 день, 3 дня, 7 дней и 21 день — это кривая забывания Эббингауза. Пассивное перечитывание почти не работает: пересказывай вслух, задавай себе вопросы, решай задачи по теме. Сон после учёбы закрепляет память, поэтому ночная зубрёжка хуже вечернего разбора.', 'учеба, память, повторение'),
  ('Как писать конспект', public.iskra_kb_norm('Как писать конспект'), 'Конспект — не копия лекции, а твои слова. Пиши короткими фразами, оставляй поля для вопросов. Схемы и стрелки запоминаются лучше списков. В конце каждой темы — 3 строки «что главное». Через день перепиши раздел по памяти, потом сверься с источником: расхождения — это и есть то, что надо доучить.', 'учеба, конспект, память'),
  ('Выгорание: признаки и что делать', public.iskra_kb_norm('Выгорание: признаки и что делать'), 'Три признака: истощение (нет сил даже после отдыха), безразличие к работе, чувство «я ничего не стою». Это не лень, а результат длительного напряжения. Что помогает: вернуть сон и еду, отделить работу от отдыха, сократить необязательное, поговорить с руководителем об объёме. Если месяц не отпускает — идти к психотерапевту.', 'работа, выгорание, стресс'),
  ('Телефон быстро разряжается', public.iskra_kb_norm('Телефон быстро разряжается'), 'Проверь «Аккумулятор» в настройках: какие приложения съедают больше всех. Яркость и геолокация — первые кандидаты. Полная разрядка до 0 каждый день старит батарею: держи 20–80%. Не заряжай на солнце и не оставляй на ночь под подушкой — от жары батарея изнашивается. Если за год ёмкость упала ниже 80% — пора менять.', 'техника, телефон, батарея, зарядка'),
  ('Wi-Fi медленный', public.iskra_kb_norm('Wi-Fi медленный'), 'Сначала замерь скорость на кабеле и по Wi-Fi — так поймёшь, виноват провайдер или роутер. Роутер ставь на высоту, ближе к центру квартиры, не в шкаф и не за телевизор. 2,4 ГГц дальше пробивает, 5 ГГц быстрее вблизи. Канал 2,4 ГГц переключи на 1, 6 или 11 — соседские сети мешают. Перезагрузка роутера на 30 секунд лечит половину случаев.', 'техника, wifi, интернет, роутер'),
  ('Принтер не печатает', public.iskra_kb_norm('Принтер не печатает'), 'Порядок: включён и подключён → есть бумага → не замята → картридж не пуст → в очереди печати нет зависшей задачи. Если печатает «в никуда» — выбери его принтером по умолчанию. Ошибка связи по Wi-Fi лечится переподключением принтера к сети. Полосы и бледная печать — почисти дюзы и встряхни картридж. Драйвер не обязателен: большинство современных принтеров работают по стандартному протоколу.', 'техника, принтер, печать'),
  ('Как стирать, чтобы не портить вещи', public.iskra_kb_norm('Как стирать, чтобы не портить вещи'), 'Сортируй по цвету и типу ткани, молнии и крючки застёгивай, выворачивай наизнанку. Температура: 30–40 для повседневного, 60 для полотенец и постели, шерсть и шёлк — только деликатный режим в мешке. Кондиционер не для махровых полотенец (они перестают впитывать). Не перегружай барабан: вещам нужно место, чтобы двигаться.', 'быт, стирка, одежда'),
  ('Резервная копия фото и файлов', public.iskra_kb_norm('Резервная копия фото и файлов'), 'Правило 3-2-1: три копии, на двух разных носителях, одна — вне дома. Практически: телефон синхронизируется в облако, раз в месяц копия на внешний диск, который лежит не рядом с компьютером. Проверь восстановление хотя бы раз: копия, которую не открывали, — не копия. Пароль на архив и шифрование — если там документы.', 'техника, резервная копия, фото, диск'),
  ('Как экономить электричество', public.iskra_kb_norm('Как экономить электричество'), 'Больше всего едят нагрев и охлаждение: бойлер, обогреватель, кондиционер, электрочайник, плита. Кипяти столько, сколько нужно, закрывай кастрюлю крышкой, разогревай в микроволновке, а не в духовке. Холодильник — не рядом с плитой, дверцу не держать открытой. LED-лампы окупаются за год. Выключай то, что не используешь, а не всё «на всякий случай».', 'быт, электричество, экономия'),
  ('Уборка по 15 минут в день', public.iskra_kb_norm('Уборка по 15 минут в день'), 'Работает лучше генеральной раз в месяц: 15 минут в день по зоне (сегодня кухня, завтра пол). Правило «касания»: взял вещь — сразу на место. Поверхности освобождай полностью — порядок читается именно по ним. Раз в сезон — коробка «отдать или выбросить». Пять минут на мытьё посуды сразу после еды экономят полчаса потом.', 'быт, уборка, порядок'),
  ('Температура готовности мяса', public.iskra_kb_norm('Температура готовности мяса'), 'Курица — 74 °C в толще, фарш — 71 °C, свинина — 63 °C с отдыхом 3 минуты, рыба — 63 °C. Без термометра: курица прозрачным соком и без розового у кости. После разделки сырого мяса мой доску, нож и руки, отдельная доска для сырого — правило, а не роскошь. Мясо размораживай в холодильнике, а не на столе.', 'кулинария, мясо, готовка, безопасность'),
  ('Как хранить продукты', public.iskra_kb_norm('Как хранить продукты'), 'Холодильник 2–5 °C, морозилка −18 °C. Сырое мясо — на нижней полке, чтобы не капало на готовое. Зелень — в воде или в контейнере с бумажным полотенцем. Хлеб — в морозилку ломтями, а не в холодильник. Не ставь горячее сразу: дай остыть до тёплого. Правило «первым пришёл — первым ушёл» по срокам работает в любом доме.', 'кулинария, хранение, холодильник'),
  ('Специи: с чего начать', public.iskra_kb_norm('Специи: с чего начать'), 'Соль — усилитель вкуса, добавляй в процессе, а не только в конце. Базовый набор: перец, паприка, кумин (для мяса и бобовых), орегано и базилик (для томатов), кориандр, лавровый лист, куркума. Специи раскрываются в жире: обжарь 30 секунд в масле. Кладут понемногу и за пару минут до готовности. Молотые быстро выдыхаются — храни в закрытой банке в темноте.', 'кулинария, специи, вкус'),
  ('Простое тесто', public.iskra_kb_norm('Простое тесто'), 'Базовое дрожжевое: 500 г муки, 300 мл тёплой воды (не горячее 40 °C), 7 г сухих дрожжей, 10 г соли, ложка сахара. Замеси до гладкости, накрой и оставь в тепле на 1–1,5 часа до удвоения. Обомни, сформируй, дай подойти 30 минут, пеки 200–220 °C. Муку добавляй понемногу: тесто должно быть мягким и чуть липким, а не крутым.', 'кулинария, тесто, выпечка'),
  ('Загранпаспорт: сколько делается', public.iskra_kb_norm('Загранпаспорт: сколько делается'), 'В России загранпаспорт нового образца оформляют до 3 месяцев, старого — тоже до 3 месяцев, но сроки зависят от места подачи. Подаёшь через Госуслуги, МФЦ или напрямую в подразделение по вопросам миграции по месту жительства. Паспорт действителен 10 лет (нового образца). Проверь срок действия перед поездкой: многие страны требуют минимум 6 месяцев запаса.', 'путешествия, паспорт, документы'),
  ('Ручная кладь: что можно', public.iskra_kb_norm('Ручная кладь: что можно'), 'Жидкости — в ёмкостях до 100 мл, все в одном прозрачном пакете до 1 литра. Нож, ножницы больше 6 см, инструменты — в багаж. Пауэрбанк — только в ручную кладь, не в чемодан. Лекарства бери с рецептом или инструкцией, особенно с содержанием наркотических веществ. Габариты и вес ручной клади зависят от авиакомпании: смотри тариф, а не общие правила.', 'путешествия, самолет, ручная кладь'),
  ('Страховка в поездке', public.iskra_kb_norm('Страховка в поездке'), 'Медицинская страховка для шенгена обязательна, для большинства других стран — нет, но нужна: лечение за границей дорогое. Проверь, что покрывает: госпитализация, скорая, стоматология, репатриация. Активный отдых (лыжи, дайвинг) часто исключён — покупается отдельно. Документы держи в телефоне и бумагой: номер полиса и телефон ассистанса на видном месте.', 'путешествия, страховка, поездка'),
  ('Что взять в поездку на неделю', public.iskra_kb_norm('Что взять в поездку на неделю'), 'Одежда по принципу капсулы: 3 верха, 2 низа, одна тёплая вещь, одна обувь на выход. Собирай вещи за неделю до выезда и вычеркни треть — обычно обходишься без неё. Документы, деньги и лекарства — в ручной клади. Зарядки и переходник для розеток. Копии документов в облаке и на бумаге. Не бери «на всякий случай» больше двух вещей.', 'путешествия, сборы, чемодан'),
  ('Как вести себя в конфликте', public.iskra_kb_norm('Как вести себя в конфликте'), 'Сначала факт, потом чувство, потом просьба: «Когда встреча переносится в последний момент, я не успеваю подготовиться. Давай предупреждать хотя бы за час». Говори о поведении, не о личности: «ты безответственный» — это удар, а не аргумент. Дай паузу, если градус растёт: 20 минут тишины снижают накал. Цель — решить задачу, а не выиграть спор.', 'психология, конфликт, общение'),
  ('Личные границы', public.iskra_kb_norm('Личные границы'), 'Граница — это про то, что ты делаешь, а не про то, что должны другие. «Я не беру рабочие звонки после десяти» — граница. «Ты не должен мне звонить» — требование. Отказ не обязан быть оправданием: «Нет, не смогу» — полный ответ. Чувство вины при первом отказе нормально и проходит. Люди, которым важны только твои «да», — не те, ради кого стоит их стирать.', 'психология, границы, общение'),
  ('Если накрывает тревога', public.iskra_kb_norm('Если накрывает тревога'), 'При тревоге тело ускоряется без реальной опасности. Дыхание на 4–7–8: вдох 4 секунды, задержка 7, выдох 8, три круга. Заземление 5-4-3-2-1: назови 5 вещей, которые видишь, 4 которые слышишь, 3 которых касаешься, 2 запаха, 1 вкус. Тревога — волна: она спадает сама за 10–20 минут. Если мешает жить каждый день месяц и больше — это лечится, иди к специалисту.', 'психология, тревога, стресс'),
  ('Как завести привычку', public.iskra_kb_norm('Как завести привычку'), 'Начни с абсурдно маленького шага: одна страница, одно отжимание, одна минута. Привяжи к существующему действию: «после чистки зубов — 10 приседаний». Отмечай выполнение в календаре, пропуск одного дня не рушит привычку, рушит пропуск двух подряд. Окружение важнее силы воли: кроссовки у двери работают лучше мотивации.', 'психология, привычки, дисциплина'),
  ('Как принимать критику', public.iskra_kb_norm('Как принимать критику'), 'Раздели содержание и тон: даже грубая критика может содержать полезное. Спроси конкретику: «что именно стоит сделать иначе?» — общие слова превращаются в задачу. Не оправдывайся сразу, возьми паузу «подумаю». Согласись с тем, с чем согласен, даже если остальное не принимаешь. Если критика — только обесценивание, это не про тебя, а про говорящего.', 'психология, критика, общение'),
  ('Менеджер паролей', public.iskra_kb_norm('Менеджер паролей'), 'Один длинный пароль на всё — главная дыра: утечка на одном сайте открывает остальные. Менеджер паролей хранит разные пароли под одним мастер-паролем и подставляет их сам. Мастер-пароль должен быть длинной фразой, которую ты помнишь, а не датой рождения. Включи двухфакторную защиту на самом менеджере. Запасной ключ восстановления — на бумаге, в надёжном месте.', 'безопасность, пароли, менеджер'),
  ('Как распознать фишинг', public.iskra_kb_norm('Как распознать фишинг'), 'Признаки: адрес сайта с опечаткой или лишними буквами, срочность («аккаунт удалят через 24 часа»), просьба ввести пароль после перехода по ссылке, вложение неожиданно, обращение без имени. Проверяй адрес до клика: наведи и посмотри, куда ведёт. Банк и госуслуги не просят пароли по почте. Зашёл по ссылке — не вводи данные, закрой и зайди на сайт вручную.', 'безопасность, фишинг, мошенники'),
  ('Двухфакторная защита', public.iskra_kb_norm('Двухфакторная защита'), 'Пароль плюс второй фактор: код из приложения, ключ-брелок или СМС. СМС слабее — её можно перехватить при переносе номера. Лучше приложение-аутентификатор или аппаратный ключ. Приложение-аутентификатор даёт код, который живёт 30 секунд и работает без интернета. Сохрани резервные коды: потеря телефона без них = потеря аккаунта. Включай 2FA сначала на почте: через неё восстанавливают всё остальное.', 'безопасность, 2fa, аккаунт'),
  ('Публичный Wi-Fi', public.iskra_kb_norm('Публичный Wi-Fi'), 'В кафе и аэропорту считай сеть открытой книгой. Не входи в банк и не плати картой в открытой сети — только через мобильный интернет. Сайты с https шифруют трафик, но адреса всё равно видны. Отключи авто-подключение к открытым сетям и «общий доступ к файлам». Поддельная точка доступа с именем кафе — обычное дело: спрашивай точное название у персонала.', 'безопасность, wifi, общественный'),
  ('Дети и интернет', public.iskra_kb_norm('Дети и интернет'), 'Главное — не запрет, а разговор: что можно, что нет и почему. Ребёнку до 10 лет интернет только рядом со взрослым, аккаунты — с родительским контролем. Проверь настройки приватности в играх и соцсетях: настоящее имя, школа и геолокация не должны быть видны. Никогда не выкладывай лицо и адрес в открытые профили. Если что-то насторожило — ребёнку нужно знать, что его не накажут за рассказ.', 'безопасность, дети, интернет'),
  ('Как писать понятный текст', public.iskra_kb_norm('Как писать понятный текст'), 'Сначала главное: первое предложение сообщает суть. Одна мысль — один абзац, 3–4 строки. Короткие предложения читаются легче. Убирай канцелярит: «осуществляется приём заявок» → «заявки принимаем». Проверь: можно ли выкинуть слово, не потеряв смысл? Если да — выкинь. Перечитай вслух: спотыкаешься — перепиши.', 'текст, письмо, писательство'),
  ('Композиция в фотографии', public.iskra_kb_norm('Композиция в фотографии'), 'Правило третей: важное — на пересечении линий, а не в центре. Оставь воздух по направлению движения или взгляда. Задний план важен не меньше переднего: отойди или присядь, чтобы за головой не торчал столб. Свет мягче в облако и у окна, чем от прямой лампы. Снимай серию и выбирай один кадр, а не сотню подряд.', 'фото, композиция, съемка'),
  ('Как смотреть картину', public.iskra_kb_norm('Как смотреть картину'), 'Пять минут без телефона: сначала общий взгляд — куда уходит взгляд первым. Потом свет и цвет: откуда он и что освещает. Потом детали и жесты. Прочитай табличку: автор, год, название — часто оно подсказывает сюжет. Не обязательно «правильно» понимать: важнее заметить, что чувствуешь и почему. Так смотреть интереснее, чем искать скрытый смысл.', 'искусство, живопись'),
  ('Почему бывает полярная ночь', public.iskra_kb_norm('Почему бывает полярная ночь'), 'Земля вращается вокруг Солнца с наклоном оси около 23,5°. За полярным кругом (66,5° широты) зимой Солнце не поднимается над горизонтом — это полярная ночь, а летом не заходит — полярный день. Чем ближе к полюсу, тем длиннее период. В Мурманске полярная ночь длится около 40 дней, на Северном полюсе — почти полгода.', 'природа, климат, полярная ночь'),
  ('Как читать часовые пояса', public.iskra_kb_norm('Как читать часовые пояса'), 'Земля делится на 24 часовых пояса примерно по 15° долготы. В России 11 поясов: Калининград UTC+2, Москва UTC+3, Иркутск UTC+8, Петропавловск-Камчатский UTC+12. UTC — точка отсчёта без перехода на летнее время. Перелёт на восток сбивает сон сильнее, чем на запад. Часовые пояса иногда задаются политически, поэтому смещение не всегда кратно часу (например, Индия UTC+5:30).', 'природа, часовые пояса, время'),
  ('Почему трясётся земля', public.iskra_kb_norm('Почему трясётся земля'), 'Земная кора — плиты, которые медленно движутся. На границах плиты зацепляются, напряжение растёт и срывается — это землетрясение. Сила измеряется магнитудой (сколько энергии выделилось), а интенсивность в баллах — что почувствовали люди в конкретном месте. Предсказать точное время пока нельзя, поэтому сейсмостойкое строительство важнее прогнозов. После толчка — на улицу, подальше от стёкол и стен.', 'природа, землетрясение, тектоника'),
  ('Откуда берётся дождь', public.iskra_kb_norm('Откуда берётся дождь'), 'Вода испаряется с поверхности, поднимается, охлаждается и конденсируется в капли на пылинках — так образуются облака. Когда капли слипаются и становятся слишком тяжёлыми, они падают. Поэтому на побережьях и над лесами дождей больше. Дождь с грозой — когда в облаке сталкиваются ледяные кристаллы и возникает электрический заряд.', 'природа, погода, дождь'),
  ('Круговорот воды и зачем он важен', public.iskra_kb_norm('Круговорот воды и зачем он важен'), 'Испарение, конденсация, осадки, сток — замкнутый цикл. Вода не исчезает, а перераспределяется: одно и то же количество доступной пресной воды человечество использует снова и снова. Загрязнение нарушает цикл, потому что грязную воду приходится очищать. Леса и болота удерживают влагу, поэтому вырубка меняет режим рек и осадков.', 'природа, вода, экология')
